const first = $input.first().json;
let parsed = first;
if (first?.content?.[0]?.text !== undefined) parsed = first.content[0].text;
if (Array.isArray(parsed) && parsed[0]?.type === "text" && typeof parsed[0]?.text === "string") parsed = JSON.parse(parsed[0].text);
else if (typeof parsed === "string") parsed = JSON.parse(parsed);
if (!Array.isArray(parsed) && Array.isArray(parsed?.emails)) parsed = parsed.emails;
const emails = Array.isArray(parsed) ? parsed : [];
return emails.map((email) => ({ emailId: String(email.email_id ?? email.messageId ?? email.id ?? ""), subject: email.subject || "Email sans sujet", body: email?.content?.body || email.body || "", sender: email?.sender?.address || email?.sender || email?.from || "unknown", receivedAt: email.receivedDate || email.receivedAt || new Date().toISOString() })).filter((e) => e.emailId);

