const base = $("Parse MCP Envelope").item.json;
const ai = $json.output || $json;
const allowedAssignees = ["louis", "claire", "lucie"];
const allowedPriorities = ["LOW", "NORMAL", "HIGH"];
const assigneeLabelMap = { louis: "Louis", claire: "Claire", lucie: "Lucie" };
const esc = (v) => String(v ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/\"/g, "&quot;");
const actionRequired = Boolean(ai.action_required);
const responseExpected = Boolean(ai.response_expected);
const conf = Number(ai.action_confidence);
const actionConfidence = Number.isFinite(conf) ? conf : 0;
const clearlyActionable = actionRequired && responseExpected && actionConfidence >= 0.7;
if (!clearlyActionable) return null;
const assignee = allowedAssignees.includes(String(ai.assignee_username || "").toLowerCase()) ? String(ai.assignee_username).toLowerCase() : "claire";
const assigneeLabel = assigneeLabelMap[assignee] || assignee;
const priorityRaw = String(ai.priority || "NORMAL").toUpperCase();
const priority = priorityRaw === "URGENT" ? "HIGH" : (allowedPriorities.includes(priorityRaw) ? priorityRaw : "NORMAL");
const taskTitle = String(ai.task_title || base.subject || "Email a traiter").slice(0, 80);
const summary = String(ai.summary || "Synthese non fournie").slice(0, 500);
const nextAction = String(ai.next_action || "Analyser et mettre a jour le statut").slice(0, 300);
const rationale = String(ai.rationale || "Decision IA").slice(0, 300);
const excerpt = String(base.body || "").replace(/\s+/g, " " ).slice(0, 400);
const description = ["<div>", "<p><strong>Email source:</strong> " + esc(base.sender) + "<br/><strong>Sujet:</strong> " + esc(base.subject) + "</p>", "<h4>Contexte</h4>", "<p>" + esc(summary) + "</p>", "<h4>Action attendue</h4>", "<p>" + esc(nextAction) + "</p>", "<h4>Decision IA</h4>", "<ul>", "<li><strong>Assignee:</strong> " + esc(assigneeLabel) + " (" + esc(assignee) + ")</li>", "<li><strong>Priorite:</strong> " + esc(priority) + "</li>", "<li><strong>Confiance actionnable:</strong> " + esc(actionConfidence) + "</li>", "<li><strong>Justification:</strong> " + esc(rationale) + "</li>", "</ul>", "<h4>Extrait email</h4>", "<blockquote>" + esc(excerpt) + "</blockquote>", "</div>"].join("").slice(0, 5000);
return { ...base, aiDecision: { clearlyActionable, assignee, assigneeLabel, priority, actionConfidence, taskTitle, summary, nextAction, rationale }, mcpInput: { project_id: 66, title: taskTitle, description, assignee, priority } };

const fromBuild = $("Build Payload From AI").item.json;
const out = $json;
let payload = out?.content?.[0]?.text ?? out;
if (typeof payload === "string") { try { payload = JSON.parse(payload); } catch { payload = {}; } }
const taskId = Number(payload?.task_id || payload?.id || 0);
if (!taskId) {
  const sample = JSON.stringify(payload).slice(0, 800);
  throw new Error(`create_task_in_project failed or returned no task_id. payload=${sample}`);
}
return { task_id: taskId, assignee_username: fromBuild?.mcpInput?.assignee || "claire" };
